<template><view class="ui11-page"><view class="ui11-nav"><navigator open-type="navigateBack" class="ui11-nav__back">‹</navigator><text class="ui11-nav__title">血糖记录</text><text class="ui11-nav__placeholder"></text></view><view class="form"><view class="ui11-row"><text class="ui11-row__label">血糖值</text><input v-model="form.value" class="ui11-input" type="digit" placeholder="请输入血糖值"/><text>mmol/L</text></view><view class="ui11-row"><text class="ui11-row__label">检测时段</text><picker :range="periods" @change="form.period=periods[$event.detail.value]"><text class="ui11-row__value">{{form.period}}　›</text></picker></view><view class="ui11-row"><text class="ui11-row__label">检测时间</text><input v-model="form.measuredAt" class="ui11-input" placeholder="2026-06-05 16:03"/></view><view class="ui11-row"><text class="ui11-row__label">备注</text><input v-model="form.remark" class="ui11-input" placeholder="添加备注（选填）"/></view></view><view class="ui11-fixed-action"><view class="ui11-primary-btn" @click="submit">{{loading?'保存中…':'保存'}}</view></view></view></template>
<script>import { saveGlucose } from '@/api/health.js'; export default {data(){return{loading:false,periods:['早餐前','午餐前','晚餐前','睡前'],form:{value:'',period:'晚餐前',measuredAt:'',remark:''}}},methods:{submit(){if(!this.form.value)return uni.showToast({title:'请填写血糖值',icon:'none'});this.loading=true;saveGlucose(this.form).then(()=>uni.showToast({title:'保存成功',icon:'success'})).catch(()=>uni.showToast({title:'健康服务暂未接入',icon:'none'})).finally(()=>this.loading=false)}}}</script>
<style lang="scss" scoped>.form{padding:0 12rpx;background:#fff}.ui11-input{flex:1;text-align:right;color:#333;font-size:30rpx}.ui11-row picker{flex:1;text-align:right}</style>
